// 5-STAGE RISC PIPELINE (Conceptual Model)

// The Stages of Instruction Execution
typedef enum { FETCH, DECODE, EXECUTE, MEMORY, WRITEBACK } Stage;

// Inter-stage Registers (Latches) holding instruction state
struct PipelineRegisters {
    // Instruction Data between stages
    Stage FD_Latch; // Fetch -> Decode
    Stage DE_Latch; // Decode -> Execute
    Stage EM_Latch; // Execute -> Memory
    Stage MW_Latch; // Memory -> Write Back
};

